def word_frequencies(text, min_len=3):
    words = [w.strip(".,!?").lower() for w in text.split()]
    words = [w for w in words if len(w) >= min_len]
    counts = {w: words.count(w) for w in set(words)}
    top = sorted(counts.items(), key=lambda kv: -kv[1])
    return [(w, n) for w, n in top if n > 1]

from itertools import product

def make_grid(rows, cols, fill=0):
    return [[fill for _ in range(cols)] for _ in range(rows)]

def neighbours(grid, r, c):
    deltas = [(dr, dc) for dr, dc in product((-1, 0, 1), repeat=2) if dr or dc]
    return [
        grid[r + dr][c + dc]
        for dr, dc in deltas
        if 0 <= r + dr < len(grid) and 0 <= c + dc < len(grid[0])
    ]

def transpose(grid):
    return [list(col) for col in zip(*grid)]

def flatten(grid):
    return [cell for row in grid for cell in row]

async function fetchJson(url, retries = 3) {
  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      const res = await fetch(url);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return await res.json();
    } catch (err) {
      if (attempt === retries) throw err;
      await new Promise((r) => setTimeout(r, 200 * 2 ** attempt));
    }
  }
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export async function loadAll(urls, { limit = 4, timeout = 5000 } = {}) {
  const results = new Array(urls.length);
  let next = 0;

  async function worker() {
    while (next < urls.length) {
      const i = next++;
      const ctrl = new AbortController();
      const timer = setTimeout(() => ctrl.abort(), timeout);
      try {
        const res = await fetch(urls[i], { signal: ctrl.signal });
        results[i] = { ok: res.ok, data: await res.text() };
      } catch (error) {
        results[i] = { ok: false, error: String(error) };
      } finally {
        clearTimeout(timer);
      }
      await sleep(50);
    }
  }

  await Promise.all(Array.from({ length: limit }, worker));
  return results;
}

\section{Fourier series}
Let $f$ be $2\pi$-periodic and integrable on $[-\pi, \pi]$. Then
\begin{equation}
  f(x) \sim \frac{a_0}{2} + \sum_{n=1}^{\infty}
    \left( a_n \cos(nx) + b_n \sin(nx) \right),
\end{equation}
where the coefficients are given by
\begin{align}
  a_n &= \frac{1}{\pi} \int_{-\pi}^{\pi} f(x) \cos(nx) \, dx, \\
  b_n &= \frac{1}{\pi} \int_{-\pi}^{\pi} f(x) \sin(nx) \, dx.
\end{align}
By Parseval's identity,
\[
  \frac{1}{\pi} \int_{-\pi}^{\pi} |f(x)|^2 \, dx
    = \frac{a_0^2}{2} + \sum_{n=1}^{\infty} \left( a_n^2 + b_n^2 \right).
\]
